def shortest_over_quota(usage, quota):
    best = 0
    total = 0
    start = 0
    for end, amount in enumerate(usage):
        total += amount
        while total >= quota:
            length = end - start + 1
            if best == 0 or length < best:
                best = length
            total -= usage[start]
            start += 1
    return best
